  1	/**
  2	 * Extracts `@handle` mentions from comment bodies and resolves them to member
  3	 * ids.
  4	 *
  5	 * A handle is the local part of a member's email address, lowercased — that
  6	 * is what the comment composer autocompletes and what `CommentService` feeds
  7	 * to the notification fan-out, so extraction and resolution must agree
  8	 * exactly. Mentions inside code spans and fenced blocks are ignored.
  9	 */
 10	import type { UserId } from "@/types/common";
 11	import type { MemberWithUser } from "@/types/member";
 12	
 13	/** `@` must start the line or follow whitespace/punctuation, never an email. */
 14	const MENTION_PATTERN = /(^|[\s(<[])@([a-z0-9][a-z0-9._-]{0,38}[a-z0-9])/gi;
 15	
 16	function withoutCode(body: string): string {
 17	  return body.replace(/```[\s\S]*?```/g, " ").replace(/`[^`]*`/g, " ");
 18	}
 19	
 20	/** The handle Taskflow addresses a member by, derived from their email. */
 21	export function handleOf(member: MemberWithUser): string {
 22	  return (member.user.email.split("@")[0] ?? "").toLowerCase();
 23	}
 24	
 25	/** Every distinct handle mentioned, in first-appearance order. */
 26	export function extractMentions(body: string): readonly string[] {
 27	  const seen = new Set<string>();
 28	  const handles: string[] = [];
 29	
 30	  for (const match of withoutCode(body).matchAll(MENTION_PATTERN)) {
 31	    const handle = (match[2] ?? "").toLowerCase();
 32	    if (handle === "" || seen.has(handle)) continue;
 33	    seen.add(handle);
 34	    handles.push(handle);
 35	  }
 36	
 37	  return handles;
 38	}
 39	
 40	/**
 41	 * Maps the mentions in `body` onto the ids of members who actually exist in
 42	 * the organization. Unknown handles are silently dropped — a typo must never
 43	 * fail the comment write.
 44	 */
 45	export function resolveMentions(
 46	  body: string,
 47	  members: readonly MemberWithUser[],
 48	): readonly UserId[] {
 49	  const byHandle = new Map<string, UserId>();
 50	  for (const member of members) {
 51	    // Read-only members cannot take part in a discussion, so pinging them
 52	    // only produces an alert they can do nothing about.
 53	    if (member.role === "viewer") continue;
 54	    byHandle.set(handleOf(member), member.userId);
 55	  }
 56	
 57	  const resolved: UserId[] = [];
 58	  const seen = new Set<UserId>();
 59	  for (const handle of extractMentions(body)) {
 60	    const userId = byHandle.get(handle);
 61	    if (userId === undefined || seen.has(userId)) continue;
 62	    seen.add(userId);
 63	    resolved.push(userId);
 64	  }
 65	
 66	  return resolved;
 67	}
 68	
 69	/** Wraps every mention in a span so the comment renderer can style it. */
 70	export function highlightMentions(body: string): string {
 71	  return body.replace(
 72	    MENTION_PATTERN,
 73	    (_match, prefix: string, handle: string) =>
 74	      `${prefix}<span class="mention">@${handle}</span>`,
 75	  );
 76	}
  1	/**
  2	 * Token-bucket limiter applied to invites, comments, search and password
  3	 * resets.
  4	 *
  5	 * Buckets are keyed by `(orgId, bucketKey)` and held in process — Taskflow
  6	 * runs single-writer, and the corpus has no external cache. Capacity scales
  7	 * with the org's plan through `getPlanLimits()`, so a growth org is not held
  8	 * to a free org's ceiling; the per-bucket shape below is the base rate.
  9	 */
 10	import { getPlanLimits } from "@/config/plan-limits";
 11	import type { PlanId } from "@/types/billing";
 12	import type { IsoTimestamp, OrgId } from "@/types/common";
 13	import { toIsoTimestamp } from "@/types/common";
 14	
 15	export type RateLimitVerdict = {
 16	  allowed: boolean;
 17	  remaining: number;
 18	  resetAt: IsoTimestamp;
 19	};
 20	
 21	export type RateLimitConfig = { capacity: number; refillPerMinute: number };
 22	
 23	export const RATE_LIMIT_BUCKETS: Readonly<Record<string, RateLimitConfig>> = {
 24	  "member:invite": { capacity: 20, refillPerMinute: 2 },
 25	  "comment:create": { capacity: 60, refillPerMinute: 20 },
 26	  "issue:create": { capacity: 60, refillPerMinute: 20 },
 27	  "search:query": { capacity: 120, refillPerMinute: 60 },
 28	  "auth:password-reset": { capacity: 5, refillPerMinute: 1 },
 29	  "webhook:deliver": { capacity: 100, refillPerMinute: 50 },
 30	};
 31	
 32	/** Applied to any key not in the table above. */
 33	const DEFAULT_BUCKET: RateLimitConfig = { capacity: 30, refillPerMinute: 10 };
 34	
 35	type BucketState = { tokens: number; updatedAt: number };
 36	
 37	const buckets = new Map<string, BucketState>();
 38	
 39	/** Plan-aware org context; services set this when they know the org's plan. */
 40	const planByOrg = new Map<OrgId, PlanId>();
 41	
 42	/** Records an org's plan so subsequent bucket sizes scale with its quota. */
 43	export function setOrgPlan(orgId: OrgId, plan: PlanId): void {
 44	  planByOrg.set(orgId, plan);
 45	}
 46	
 47	export function getBucketConfig(bucketKey: string): RateLimitConfig {
 48	  return RATE_LIMIT_BUCKETS[bucketKey] ?? DEFAULT_BUCKET;
 49	}
 50	
 51	/**
 52	 * Scales the base bucket by the org's hourly API allowance, so the limiter
 53	 * and the plan catalogue can never drift apart: the plan is the source of
 54	 * the ceiling, this table only sets the relative shape.
 55	 */
 56	function configFor(orgId: OrgId, bucketKey: string): RateLimitConfig {
 57	  const base = getBucketConfig(bucketKey);
 58	  const plan = planByOrg.get(orgId) ?? "free";
 59	  const hourly = getPlanLimits(plan).apiRequestsPerHour;
 60	  const factor = Number.isFinite(hourly) ? Math.max(1, hourly / 100) : 100;
 61	
 62	  return {
 63	    capacity: Math.min(base.capacity * factor, base.capacity * 100),
 64	    refillPerMinute: Math.min(
 65	      base.refillPerMinute * factor,
 66	      base.refillPerMinute * 100,
 67	    ),
 68	  };
 69	}
 70	
 71	/**
 72	 * Spends `cost` tokens from the bucket, refilling first for the elapsed time.
 73	 * Async because the production limiter is expected to move behind a store —
 74	 * every call site already awaits it.
 75	 */
 76	export async function consumeRateLimit(
 77	  orgId: OrgId,
 78	  bucketKey: string,
 79	  cost = 1,
 80	): Promise<RateLimitVerdict> {
 81	  const config = configFor(orgId, bucketKey);
 82	  const key = `${orgId}:${bucketKey}`;
 83	  const nowMs = Date.now();
 84	
 85	  const state = buckets.get(key) ?? { tokens: config.capacity, updatedAt: nowMs };
 86	  const elapsedMinutes = (nowMs - state.updatedAt) / 60_000;
 87	  const tokens = Math.min(
 88	    config.capacity,
 89	    state.tokens + elapsedMinutes * config.refillPerMinute,
 90	  );
 91	
 92	  const allowed = tokens >= cost;
 93	  const remaining = allowed ? tokens - cost : tokens;
 94	  buckets.set(key, { tokens: remaining, updatedAt: nowMs });
 95	
 96	  const deficit = allowed ? config.capacity - remaining : cost - remaining;
 97	  const minutesToReset =
 98	    config.refillPerMinute > 0 ? Math.max(0, deficit) / config.refillPerMinute : 0;
 99	
100	  return {
101	    allowed,
102	    remaining: Math.floor(remaining),
103	    resetAt: toIsoTimestamp(new Date(nowMs + minutesToReset * 60_000)),
104	  };
105	}
106	
107	/** Test-only: drops every bucket and org plan association. */
108	export function resetRateLimits(): void {
109	  buckets.clear();
110	  planByOrg.clear();
111	}
  1	import type { ArchiveScope, IsoTimestamp, SoftDeletable } from "@/types/common";
  2	import { toIsoTimestamp } from "@/types/common";
  3	
  4	/**
  5	 * Soft-delete conventions.
  6	 *
  7	 * Issues, projects and comments are never physically removed — they get an
  8	 * `archived_at` timestamp. Repositories must express "live rows only" through
  9	 * these helpers so the predicate stays in one place; a raw
 10	 * `isNull(table.archivedAt)` sprinkled through the data layer is exactly the
 11	 * drift this module prevents.
 12	 */
 13	
 14	export function isArchived(row: SoftDeletable): boolean {
 15	  return row.archivedAt !== null;
 16	}
 17	
 18	export function isLive(row: SoftDeletable): boolean {
 19	  return row.archivedAt === null;
 20	}
 21	
 22	/** Filters an in-memory collection according to an `ArchiveScope`. */
 23	export function applyArchiveScope<T extends SoftDeletable>(
 24	  rows: readonly T[],
 25	  scope: ArchiveScope = {},
 26	): readonly T[] {
 27	  return scope.includeArchived === true ? rows : rows.filter(isLive);
 28	}
 29	
 30	/** True when the repository should add the `archived_at IS NULL` predicate. */
 31	export function shouldFilterArchived(scope: ArchiveScope = {}): boolean {
 32	  return scope.includeArchived !== true;
 33	}
 34	
 35	/** The column patch that archives a row. */
 36	export function archivePatch(now: Date = new Date()): {
 37	  archivedAt: IsoTimestamp;
 38	  updatedAt: IsoTimestamp;
 39	} {
 40	  const stamp = toIsoTimestamp(now);
 41	  return { archivedAt: stamp, updatedAt: stamp };
 42	}
 43	
 44	/** The column patch that restores an archived row. */
 45	export function restorePatch(now: Date = new Date()): {
 46	  archivedAt: null;
 47	  updatedAt: IsoTimestamp;
 48	} {
 49	  return { archivedAt: null, updatedAt: toIsoTimestamp(now) };
 50	}
 51	
 52	export class AlreadyArchivedError extends Error {
 53	  readonly code = "conflict" as const;
 54	
 55	  constructor(readonly entity: string, readonly id: string) {
 56	    super(`${entity} ${id} is already archived.`);
 57	    this.name = "AlreadyArchivedError";
 58	  }
 59	}
 60	
 61	/** Guard for archive actions, so double-archiving is a domain-level conflict. */
 62	export function assertNotArchived(
 63	  entity: string,
 64	  id: string,
 65	  row: SoftDeletable,
 66	): void {
 67	  if (isArchived(row)) {
 68	    throw new AlreadyArchivedError(entity, id);
 69	  }
 70	}

