  return {
    id: brandId<CommentId>(row.id),
    orgId: brandId<OrgId>(row.orgId),
    issueId: brandId<IssueId>(row.issueId),
    authorId: brandId<UserId>(row.authorId),
    body: row.body,
    parentId: row.parentId === null ? null : brandId<CommentId>(row.parentId),
    editedAt: row.editedAt,
    mentionedUserIds: parseJsonArray<UserId>(row.mentionedUserIds),
    createdAt: brandStamp(row.createdAt),
    updatedAt: brandStamp(row.updatedAt),
    archivedAt: brandStampOrNull(row.archivedAt),
  };
}

export function toNotification(row: NotificationRow): Notification {
  return {
    id: brandId<NotificationId>(row.id),
    orgId: brandId<OrgId>(row.orgId),
    recipientId: brandId<UserId>(row.recipientId),
    kind: row.kind,
    title: row.title,
    body: row.body,
    href: row.href,
    actorId: row.actorId === null ? null : brandId<UserId>(row.actorId),
}

export async function getIssue(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<IssueWithRelations> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  const labels = await labelRepo.listLabelsForIssues(orgId, [issue.id]);

  return {
    issue,
    labels: labels[issue.id] ?? [],
    commentCount: await commentRepo.countComments(orgId, issue.id),
    attachmentCount: (await attachmentRepo.listAttachments(orgId, issue.id))
      .length,
  };
}

export async function listIssues(
  actor: Actor,
  input: IssueFilterInput,
): Promise<Page<Issue>> {
  assertOrgScope(actor, input.orgId);
  // A cross-project list is an org-wide read; per-project visibility is
  // enforced when the caller opens an individual issue.
  assertCan(actor, "issue:read", orgResource(input.orgId));
  return issueRepo.listIssues(input);
}

