     1	/**
     2	 * Threaded comment list, hiding delete for non-authors.
     3	 *
     4	 * Must call (do not reimplement): can
     5	 */
     6	import { EmptyState } from "@/components/ui/empty-state";
     7	import { can } from "@/lib/permissions";
     8	import { isLive } from "@/lib/soft-delete";
     9	import type { CommentId } from "@/types/common";
    10	import type { CommentThreadNode } from "@/types/comment";
    11	import type { Actor } from "@/types/member";
    12	import type { ReactElement } from "react";
    13	import { organizationResource } from "../permission/resources";
    14	import { CommentItem } from "./comment-item";
    15	
    16	export type CommentThreadProps = {
    17	  nodes: readonly CommentThreadNode[];
    18	  actor: Actor;
    19	  onDelete: (commentId: CommentId) => void;
    20	  onEdit?: (commentId: CommentId) => void;
    21	};
    22	
    23	/** Oldest first: a discussion reads top to bottom, unlike a feed. */
    24	export function orderThread(
    25	  nodes: readonly CommentThreadNode[],
    26	): readonly CommentThreadNode[] {
    27	  return [...nodes].sort((a, b) =>
    28	    a.comment.createdAt.localeCompare(b.comment.createdAt),
    29	  );
    30	}
    31	
    32	export function CommentThread(props: CommentThreadProps): ReactElement | null {
    33	  const { nodes, actor, onDelete, onEdit } = props;
    34	
    35	  if (!can(actor, "comment:read", organizationResource(actor.orgId))) {
    36	    return null;
    37	  }
    38	
    39	  const visible = orderThread(nodes).filter((node) => isLive(node.comment));
    40	
    41	  if (visible.length === 0) {
    42	    return <EmptyState title="No comments yet" description="Start the thread." />;
    43	  }
    44	
    45	  return (
    46	    <ol className="comment-thread divide-y">
    47	      {visible.map((node) => (
    48	        <li key={node.comment.id}>
    49	          <ol>
    50	            <CommentItem
    51	              comment={node.comment}
    52	              actor={actor}
    53	              depth={0}
    54	              onDelete={onDelete}
    55	              {...(onEdit !== undefined ? { onEdit } : {})}
    56	            />
    57	            {node.replies
    58	              .filter(isLive)
    59	              .sort((a, b) => a.createdAt.localeCompare(b.createdAt))
    60	              .map((reply) => (
    61	                <CommentItem
    62	                  key={reply.id}
    63	                  comment={reply}
    64	                  actor={actor}
    65	                  depth={1}
    66	                  onDelete={onDelete}
    67	                  {...(onEdit !== undefined ? { onEdit } : {})}
    68	                />
    69	              ))}
    70	          </ol>
    71	        </li>
    72	      ))}
    73	    </ol>
    74	  );
    75	}
     1	/**
     2	 * One comment with author, timestamp and inline actions.
     3	 *
     4	 * Must call (do not reimplement): can
     5	 */
     6	import { Avatar } from "@/components/ui/avatar";
     7	import { Button } from "@/components/ui/button";
     8	import { cn } from "@/lib/cn";
     9	import { formatRelative } from "@/lib/date";
    10	import { highlightMentions } from "@/lib/mentions";
    11	import { can } from "@/lib/permissions";
    12	import { isArchived } from "@/lib/soft-delete";
    13	import type { CommentId } from "@/types/common";
    14	import type { CommentWithAuthor } from "@/types/comment";
    15	import type { Actor } from "@/types/member";
    16	import type { ReactElement } from "react";
    17	import { commentResource } from "../permission/resources";
    18	
    19	export type CommentItemProps = {
    20	  comment: CommentWithAuthor;
    21	  actor: Actor;
    22	  depth: number;
    23	  onEdit?: (commentId: CommentId) => void;
    24	  onDelete?: (commentId: CommentId) => void;
    25	};
    26	
    27	/** Replies are indented once; deeper nesting is flattened by the thread. */
    28	const INDENT_REM = 2;
    29	
    30	export function CommentItem(props: CommentItemProps): ReactElement | null {
    31	  const { comment, actor, depth, onEdit, onDelete } = props;
    32	  const resource = commentResource(comment);
    33	
    34	  // Authors may edit and delete their own comments below the matrix rank —
    35	  // that escalation lives in `can()`, not here.
    36	  const mayEdit = can(actor, "comment:update", resource);
    37	  const mayDelete = can(actor, "comment:delete", resource);
    38	
    39	  if (isArchived(comment)) {
    40	    return (
    41	      <li className="text-sm italic text-neutral-500">
    42	        This comment was deleted.
    43	      </li>
    44	    );
    45	  }
    46	
    47	  return (
    48	    <li
    49	      className={cn("comment-item flex gap-2 py-2")}
    50	      style={{ marginLeft: `${Math.min(depth, 1) * INDENT_REM}rem` }}
    51	    >
